<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account Security · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'employee',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">ACCOUNT SECURITY</p><h1>Sessions and verification</h1><p>Review access to your account and verify your email address.</p></div></header><?php if($notice):?><div class="page-flash <?=$notice['type']?>"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Email verification</h2><p><?=!empty($user['email_verified'])?'Your email address is verified.':'Your email address has not been verified.'?></p><?php if(empty($user['email_verified'])):?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="request_email_verification"><button class="button primary">Prepare verification link</button></form><?php endif;?><?php if($verificationLink&&Config::get('APP_ENV')==='local'):?><div class="invitation-result"><input value="<?=esc($verificationLink)?>" readonly></div><?php endif;?></article><article class="panel span-2"><h2>Active sessions</h2><?php foreach($userSessions as $session):?><div class="planning-row"><span><strong><?=esc($session['user_agent']?:'Unknown device')?></strong><small><?=esc(($session['ip_address']?:'Unknown IP').' · last used '.$session['last_seen_at'])?></small></span><?php if($session['revoked_at']):?><b class="state-pill">Revoked</b><?php elseif($session['current_session']):?><b class="state-pill covered">Current</b><?php else:?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="revoke_session"><input type="hidden" name="session_id" value="<?=$session['id']?>"><button class="button secondary">Revoke</button></form><?php endif;?></div><?php endforeach;?></article></section></main></body></html>
